css:
.rdd-sim-container {
    padding: 28px;
    background: #f4f1ea;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #1f2933;
}

.rdd-sim-header {
    background: linear-gradient(135deg, #0f2a4a, #1a3a6c);
    color: #f4f1ea;
    border-radius: 4px;
    padding: 28px 32px;
    margin-bottom: 24px;
    border-left: 6px solid #c97b27;
}
.rdd-sim-container .rdd-sim-org {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.18em;
    color: #c8d4e8;
    margin-bottom: 8px;
}
.rdd-sim-container .rdd-sim-header h1 {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    line-height: 1.25;
    color: #ffffff;
}
.rdd-sim-container .rdd-sim-subtitle {
    font-size: 0.95rem;
    margin: 0;
    color: #c8d4e8;
}

.rdd-sim-container .rdd-sim-period-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1a3a6c;
    color: #f4f1ea;
    border-radius: 4px;
    padding: 12px 20px;
    margin-bottom: 20px;
    font-size: 0.9rem;
}
.rdd-sim-container .rdd-sim-period-text { letter-spacing: 0.06em; }
.rdd-sim-container .rdd-sim-round-title { font-weight: 700; color: #ffd089; }

.rdd-sim-container .rdd-sim-briefing {
    background: #fffaf0;
    border: 1px solid #d6c5a3;
    border-left: 5px solid #c97b27;
    border-radius: 4px;
    padding: 18px 22px;
    margin-bottom: 24px;
}
.rdd-sim-container .rdd-sim-briefing-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: #9a5e1b;
    margin-bottom: 8px;
    font-weight: 700;
}
.rdd-sim-container .rdd-sim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2d2620;
}

.rdd-sim-container .rdd-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}
.rdd-sim-container .rdd-sim-kpi-card {
    background: #ffffff;
    border: 1px solid #d8d4cb;
    border-radius: 4px;
    padding: 18px 20px;
    border-top: 3px solid #1a3a6c;
}
.rdd-sim-container .rdd-sim-kpi-primary {
    border-top-color: #c97b27;
    background: linear-gradient(180deg, #fff7e8, #ffffff);
}
.rdd-sim-container .rdd-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #666d7a;
    margin-bottom: 6px;
    font-weight: 600;
}
.rdd-sim-container .rdd-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #1a3a6c;
    line-height: 1.1;
}
.rdd-sim-container .rdd-sim-kpi-primary .rdd-sim-kpi-value { color: #9a5e1b; }
.rdd-sim-container .rdd-sim-kpi-sub {
    font-size: 0.75rem;
    color: #666d7a;
    margin-top: 4px;
}

.rdd-sim-container .rdd-sim-controls {
    background: #ffffff;
    border: 1px solid #d8d4cb;
    border-radius: 4px;
    padding: 24px;
    margin-bottom: 24px;
}
.rdd-sim-container .rdd-sim-controls h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a3a6c;
    margin: 0 0 18px 0;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 1px solid #e0dcd1;
    padding-bottom: 10px;
}
.rdd-sim-container .rdd-sim-control-group {
    margin-bottom: 18px;
}
.rdd-sim-container .rdd-sim-control-group > label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    color: #2d2620;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}
.rdd-sim-container .rdd-sim-control-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: 16px;
}
.rdd-sim-container .rdd-sim-control-cell label {
    display: block;
    font-size: 0.78rem;
    font-weight: 600;
    color: #2d2620;
    margin-bottom: 6px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}
.rdd-sim-container .rdd-sim-hint {
    display: block;
    font-size: 0.72rem;
    color: #786b4f;
    margin-top: 4px;
    font-style: italic;
}

.rdd-sim-container .rdd-sim-controls input[type="number"],
.rdd-sim-container .rdd-sim-controls select {
    background: #ffffff;
    border: 1px solid #b8b3a5;
    color: #1f2933;
    border-radius: 4px;
    padding: 8px 12px;
    width: 100%;
    font-size: 0.95rem;
    font-family: inherit;
}
.rdd-sim-container .rdd-sim-controls select option {
    background: #ffffff;
    color: #1f2933;
}
.rdd-sim-container .rdd-sim-controls input[type="number"]:focus,
.rdd-sim-container .rdd-sim-controls select:focus {
    outline: none;
    border-color: #1a3a6c;
    box-shadow: 0 0 0 2px rgba(26,58,108,0.15);
}

.rdd-sim-container .rdd-sim-check-row {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 0;
    border-bottom: 1px dashed #e0dcd1;
}
.rdd-sim-container .rdd-sim-check-row:last-child { border-bottom: none; }
.rdd-sim-container .rdd-sim-check-row input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #1a3a6c;
    cursor: pointer;
}
.rdd-sim-container .rdd-sim-check-row label {
    margin: 0;
    font-size: 0.92rem;
    color: #2d2620;
    cursor: pointer;
    text-transform: none;
    letter-spacing: 0;
    font-weight: 500;
}

.rdd-sim-container .rdd-sim-button-row {
    display: flex;
    gap: 12px;
    margin-top: 18px;
    align-items: center;
}
.rdd-sim-container .rdd-sim-controls .btn {
    border-radius: 4px;
    font-weight: 600;
    letter-spacing: 0.04em;
    padding: 10px 22px;
    transition: 0.2s ease;
}
.rdd-sim-container .rdd-sim-controls .btn-primary {
    background: #1a3a6c;
    border-color: #1a3a6c;
    color: #ffffff;
}
.rdd-sim-container .rdd-sim-controls .btn-primary:hover {
    background: #c97b27;
    border-color: #c97b27;
}

.rdd-sim-container .rdd-sim-result {
    background: #0f2a4a;
    color: #f4f1ea;
    border-radius: 4px;
    padding: 20px 24px;
    margin-bottom: 24px;
    border-left: 5px solid #c97b27;
}
.rdd-sim-container .rdd-sim-result-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.16em;
    color: #ffd089;
    margin-bottom: 8px;
    font-weight: 700;
}
.rdd-sim-container .rdd-sim-result-text {
    font-size: 0.95rem;
    line-height: 1.6;
}

.rdd-sim-container .rdd-sim-history {
    background: #ffffff;
    border: 1px solid #d8d4cb;
    border-radius: 4px;
    padding: 20px;
    margin-bottom: 24px;
}
.rdd-sim-container .rdd-sim-history h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a3a6c;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.rdd-sim-container .rdd-sim-history table {
    width: 100%;
    font-size: 0.88rem;
}
.rdd-sim-container .rdd-sim-history th {
    background: #1a3a6c;
    color: #f4f1ea;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px;
}
.rdd-sim-container .rdd-sim-history td {
    padding: 8px 10px;
    border-bottom: 1px solid #ece9e0;
    color: #2d2620;
}
.rdd-sim-container .rdd-sim-history tbody tr:hover {
    background: #faf6ec;
}

.rdd-sim-container .rdd-sim-chart-wrap {
    background: #ffffff;
    border: 1px solid #d8d4cb;
    border-radius: 4px;
    padding: 22px;
    height: 380px;
    margin-bottom: 24px;
}
.rdd-sim-container .rdd-sim-chart-wrap h3 {
    font-size: 1rem;
    font-weight: 700;
    color: #1a3a6c;
    margin: 0 0 14px 0;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.rdd-sim-container .rdd-sim-chart-wrap canvas {
    max-height: 300px;
}

@media (max-width: 768px) {
    .rdd-sim-container { padding: 16px; }
    .rdd-sim-container .rdd-sim-header { padding: 18px 20px; }
    .rdd-sim-container .rdd-sim-header h1 { font-size: 1.2rem; }
    .rdd-sim-container .rdd-sim-kpi-grid { grid-template-columns: 1fr 1fr; }
    .rdd-sim-container .rdd-sim-period-bar { flex-direction: column; gap: 6px; align-items: flex-start; }
    .rdd-sim-container .rdd-sim-control-grid { grid-template-columns: 1fr; }
    .rdd-sim-container .rdd-sim-kpi-value { font-size: 1.5rem; }
}

/* --- EQIL a11y additions (adapter 1.1.0) --- */
.rdd-sim-container :focus-visible,
button:focus-visible, select:focus-visible, input:focus-visible {
    outline: 3px solid #0f2a4a;
    outline-offset: 2px;
}
.rdd-sim-container .rdd-sim-group-label {
    font-weight: 600;
    margin-bottom: 6px;
}
.rdd-sim-debrief dl { display: grid; grid-template-columns: auto 1fr; gap: 0.25rem 1rem; margin: 0.75rem 0; }
.rdd-sim-debrief dt { font-weight: 600; }
.rdd-sim-debrief dd { margin: 0; }
.rdd-sim-debrief-flag { font-weight: 600; color: #9a5e1b; }
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

