            if (period === 4 && (state.domainState.robustnessCount || 0) < 4) {
                return window.mySimulation.t('hint_robust_missing');
            }
            return null;
        }

        getHistoryTableConfig() {
            var self = this;
            return [
                { key: 'period', label: 'Round', i18nKey: 'col_round' },
                { key: 'results.method', label: 'Method', i18nKey: 'col_method', formatter: function(v) { return self._methodText(v); } },
                { key: 'results.estimate', label: 'Estimate (pp)', i18nKey: 'col_estimate',
                  formatter: (v) => (v === null || v === undefined) ? '—' : ('+' + Number(v).toFixed(1)) },
                { key: 'results.bias', label: 'Bias vs Truth', i18nKey: 'col_bias',
                  formatter: (v) => (v === null || v === undefined) ? '—' : (Number(v).toFixed(1) + ' pp') },
                { key: 'results.credibility', label: 'Credibility', i18nKey: 'col_credibility',
                  formatter: (v) => Math.round(Number(v) || 0) }
            ];
        }

        getPresets() { return null; }

        // results.method keeps the English label calculateResults stores; the history shows it in the active language.
        _methodText(v) {
            var s = String(v === undefined || v === null ? '' : v);
            var fixed = {
                'Naive A \u2014 Mean Comparison': 'method_naive_a',
                'Naive B \u2014 OLS with controls': 'method_naive_b',
                'Diagnostic round': 'method_diag'
            };
            if (fixed[s]) return this._t(fixed[s], s);
            var m = s.match(/^Robustness \u2014 (\d+) of 4 checks$/);
            if (m) return this._t('method_robust', s).split('{n}').join(m[1]);
            m = s.match(/^(Global polynomial order 4|Local quadratic|Local linear), h ([^,]+)(, CCT robust|, conv SE)?$/);
            if (m) {
                var keys = { 'Global polynomial order 4': 'method_global4', 'Local quadratic': 'method_local_quad', 'Local linear': 'method_local_lin' };
                var out = this._t(keys[m[1]], m[1]) + ', h ' + m[2];
                if (m[3]) out += ', ' + (m[3] === ', CCT robust' ? this._t('method_cct', 'CCT robust') : this._t('method_conv', 'conv SE'));
                return out;
            }
            return s;
        }

        _syncControlsFromDecisions(state) {
            // On resume the framework restores decisions but the DOM still showed the authored
            // defaults, so the player saw values that were not their own. Eleven controls here,
            // four of them checkboxes on the referee checklist.
            var dec = (state && state.decisions) || {};
            var vals = {
                naiveMethodSelect: dec.naiveMethod,
                diagInsightSelect: dec.diagInsight,
                bandwidthInput:    dec.bandwidth,
                polyOrderSelect:   dec.polyOrder,
                kernelSelect:      dec.kernel,
                robustSESelect:    dec.robustSE
            };
            Object.keys(vals).forEach(function(id) {
                var v = vals[id];
                if (v === undefined || v === null) return;
                if (typeof v === 'number' && isNaN(v)) return;
                var el = document.getElementById(id);
                if (el) el.value = v;
            });
            var checks = {
                checkMcCrary:   dec.mcCrary,
                checkCovBal:    dec.covBal,
                checkBwSens:    dec.bwSens,
                checkPolySens:  dec.polySens
            };
            Object.keys(checks).forEach(function(id) {
                if (checks[id] === undefined) return;
                var el = document.getElementById(id);
                if (el) el.checked = !!checks[id];
            });
        }

        _updateBriefing(state) {
            var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
            // Past round 4 the memo is filed. The period used to clamp to 4, leaving the round 4
            // control group and a live Submit Decision button on screen with nothing left to run.
            if (period > 4) {
                var ctlEl = document.querySelector('.rdd-sim-controls');
                var rowEl = document.querySelector('.rdd-sim-button-row');
                if (rowEl && rowEl.style) rowEl.style.display = 'none';
                if (ctlEl && ctlEl.style) ctlEl.style.display = 'none';
                var doneT = document.getElementById('roundTitle');
                var doneB = document.getElementById('briefingText');
                if (doneT) doneT.innerHTML = this._t('round_complete_title', 'Memo filed');
                if (doneB) doneB.innerHTML = this._t('round_complete_brief', 'All four rounds are on the record.');
                return;
            }
            if (period < 1) period = 1;
            var idx = period - 1;

            var t = (window.mySimulation && window.mySimulation.t)
                ? window.mySimulation.t.bind(window.mySimulation)
                : function(k) { return k; };

            var titleEl = document.getElementById('roundTitle');
            var briefEl = document.getElementById('briefingText');
            if (titleEl) titleEl.innerHTML = t('round' + (idx + 1) + '_title');
            if (briefEl) briefEl.innerHTML = t('round' + (idx + 1) + '_brief');

            var groups = ['round1Controls', 'round2Controls', 'round3Controls', 'round4Controls'];
            for (var i = 0; i < groups.length; i++) {
                var el = document.getElementById(groups[i]);
                if (el) el.style.display = (i === idx) ? 'block' : 'none';
            }
        }

